import { SignalProvider } from '@mastra/core/signals'
import { z } from 'zod'

// 将已由应用接收的制度更新，映射到订阅这份制度的线程。
export class PolicyEvents extends SignalProvider {
  id = 'policy-events'

  watch (target, documentId) {
    return this.subscribe(target, documentId)
  }

  async handleWebhook ({ body }) {
    const event = z.object({ documentId: z.string().min(1), version: z.number().int().positive() }).parse(body)
    const subscriptions = this.getSubscriptionsForResource(event.documentId)
    for (const target of subscriptions) {
      await this.notify({
        source: this.id, kind: 'policy-updated', priority: 'high',
        summary: `制度 ${event.documentId} 已更新到第 ${event.version} 版，请重新核对引用。`,
        payload: event, dedupeKey: `${event.documentId}:${event.version}`
      }, { resourceId: target.resourceId, threadId: target.threadId })
    }
    return { status: 200, body: { matched: subscriptions.length } }
  }
}

import assert from 'node:assert/strict'
import { PolicyEvents } from './policy-events.js'
import { createThreadRuntime } from './thread-runtime.js'

// 事件提供方保存来源订阅，通知策略仍只写入收件箱。
const events = new PolicyEvents()
// 只让当前线程订阅差旅制度，不订阅其他文件。
const runtime = await createThreadRuntime('providers', {
  signals: [events], notifications: { deliveryPolicy: { default: 'persist' } }
})
try {
  events.watch(runtime.thread, 'travel-2026')
  console.log('匹配事件：', await events.handleWebhook({ body: { documentId: 'travel-2026', version: 2 } }))
  console.log('不匹配事件：', await events.handleWebhook({ body: { documentId: 'other-policy', version: 2 } }))
  const inbox = await runtime.storage.getStore('notifications')
  const records = await inbox.listNotifications(runtime.thread)
  assert.equal(records.length, 1)
  console.log('当前线程收到的通知：', records.map(record => record.summary))
} finally {
  events.stop()
  await runtime.close()
}

